import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Targeted Attacks and Anatomy","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/targeting-and-anatomy.md","filePath":"en/guide/combat/targeting-and-anatomy.md"}'),o={name:"en/guide/combat/targeting-and-anatomy.md"};function r(s,e,l,c,d,m){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="targeted-attacks-and-anatomy" tabindex="-1">Targeted Attacks and Anatomy <a class="header-anchor" href="#targeted-attacks-and-anatomy" aria-label="Permalink to &quot;Targeted Attacks and Anatomy&quot;">​</a></h1><ul><li><strong>Design status:</strong> Accepted optional targeting direction and scoped Anatomy; Proposed richer interactions.</li><li><strong>Implementation:</strong> Qualitative Anatomy is integrated; player-selected aiming is deferred.</li><li><strong>Availability:</strong> no new live behavior established here; current configuration not inspected.</li><li><strong>Verification:</strong> documentation reviewed 2026-10-08; no new playtest. Existing evidence is scoped in <a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">combat status</a>.</li></ul><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Anatomy provides scoped qualitative condition information, not hidden numeric certainty.</li><li>A requested body region expresses intent; the server resolves the actual outcome.</li><li>Richer targeting and information interactions remain proposals; aiming is not a free extra swing.</li></ul><h2 id="information-helps-you-choose" tabindex="-1">Information helps you choose <a class="header-anchor" href="#information-helps-you-choose" aria-label="Permalink to &quot;Information helps you choose&quot;">​</a></h2><p>The current scoped Anatomy experiment can report qualitative condition for the seven regions on a successful assessment. It does not reveal exact integrity, trauma values or hidden aim probabilities. Privileged Lab diagnostics are separate from what a character knows.</p><h2 id="a-choice-is-an-attempt" tabindex="-1">A choice is an attempt <a class="header-anchor" href="#a-choice-is-an-attempt" aria-label="Permalink to &quot;A choice is an attempt&quot;">​</a></h2><p>Choosing an arm should express intent, not permanently guarantee every hit there. The server still resolves whether an attack occurs, whether it hits and where it lands. Optional aiming must coexist with ordinary automatic attacks; selecting a region is not a free extra swing.</p><p>Future targeting may depend on openings, position, weapon, execution, character skill, the defender&#39;s movement, available information and fatigue. Anatomy could support Healing and hunting/skinning knowledge, while Tactics helps interpret opportunities and Arms Lore helps interpret equipment. These extensions do not broaden current disclosure automatically.</p><p><a href="/Syrolands-Public/en/game-design/combat/targeting.html">Full targeting specification</a> · <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">Accepted Anatomy disclosure</a> · <a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">Combat status</a>.</p><p><a href="/Syrolands-Public/en/guide/combat/overview.html">Back to Combat overview</a></p>',11)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
